Map<String,String> environment(int c){final p='$owned/c$c';final e=<String,String>{'PATH':'/usr/bin:/bin','TMPDIR':'/home/bsutton/.cache/rv4-security-20261011','HOME':'$p/home','XDG_CONFIG_HOME':'$p/config','XDG_CACHE_HOME':'$p/cache','XDG_STATE_HOME':'$p/state','XDG_DATA_HOME':'$p/data','LOCKBOX_SESSION_AGENT_DIR':'$p/agent','LOCKBOX_SESSION_AGENT_LOG':'$p/agent.log','LOCKBOX_VAULT_DIR':'$p/vault','LOCKBOX_PLATFORM_SECRET_STORE':'disabled','LOCKBOX_ADD_PROGRESS':'off'};for(final k in ['HOME','XDG_CONFIG_HOME','XDG_CACHE_HOME','XDG_STATE_HOME','XDG_DATA_HOME','LOCKBOX_SESSION_AGENT_DIR','LOCKBOX_VAULT_DIR'])Directory(e[k]!).createSync(recursive:true);require(utf8.encode('${e['LOCKBOX_SESSION_AGENT_DIR']}/agent.sock').length<=100,'socket');return e;}
ProcessResult run(List<String> argv,Map<String,String> env,String label,{int maximum=180,bool mustPass=true,bool cleanup=false}){final remaining=cleanup?maximum:1800-wall.elapsed.inSeconds-60;require(remaining>0,'30minute cap');final seconds=remaining<maximum?remaining:maximum;final command=['--kill-after=10s','$seconds',...argv];final r=Process.runSync('/usr/bin/timeout',command,environment:env,includeParentEnvironment:false);final stem='$raw/commands/${(counter++).toString().padLeft(5,'0')}-$label';File(stem).parent.createSync(recursive:true);File('$stem.stdout').writeAsStringSync(r.stdout as String);File('$stem.stderr').writeAsStringSync(r.stderr as String);save('$stem.json',{'argv':['/usr/bin/timeout',...command],'exit_code':r.exitCode,'timed_out':r.exitCode==124||r.exitCode==137});if(mustPass)require(r.exitCode==0,'Command failed: $label, retainedlogs');return r;}
int diskBytes(String path){final d=Directory(path);if(!d.existsSync())return 0;var n=0;for(final f in d.listSync(recursive:true,followLinks:false)){if(f is File)n+=f.lengthSync();}return n;}
void budget(int next){final roots=[owned,'/home/bsutton/.cache/rv-many-20261012','/home/bsutton/.cache/revault-native-public-20261011','/home/bsutton/.cache/rv-credential-20261012','$worktree/rust/target/credential-open-20261012/bin','$worktree/rust/target/parallel-extraction-202612/bin','$worktree/rust/target/native-public-20261011/bin','$worktree/rust/target/native-extract-cache-budget-20261011/bin',evidence];final total=roots.map(diskBytes).fold<int>(0,(a,b)=>a+b);require(total+next<=24*1024*1024*1024,'24GiB ownedcap');final r=Process.runSync('/usr/bin/df',['-Pk',owned]);require(r.exitCode==0,'df');final fields=(r.stdout as String).trim().split('\n').last.split(RegExp(r'\s+'));require(int.parse(fields[3])*1024>=next+2*1024*1024*1024,'headroom');}
void agent(int c,{required bool start}){final e=environment(c);final socket='${e['LOCKBOX_SESSION_AGENT_DIR']}/agent.sock';if(start){final r=run([cli,'session','--format','json'],e,'session$c',maximum:20);final rows=(r.stdout as String).split('\n').where((v)=>v.trim().isNotEmpty).map(jsonDecode);require(rows.any((v)=>v is Map&&v['kind']=='agent'&&v['state']=='running'&&v['value']=='yes'),'agent roundtrip');run(['/usr/bin/test','-S',socket],e,'socket$c',maximum:5);}else{final present=run(['/usr/bin/test','-S',socket],e,'cleanup-present$c',maximum:5,mustPass:false,cleanup:true);if(present.exitCode==1)return;require(present.exitCode==0,'Socket inspection failed');run([cli,'session','stop'],e,'stop$c',maximum:20,cleanup:true);run(['/usr/bin/test','!','-S',socket],e,'stopped$c',maximum:5,cleanup:true);}}
void cleanupAgents(List<int> cases){final results=<Map<String,dynamic>>[];for(final c in cases){try{agent(c,start:false);results.add({'case':c,'stopped':true});}catch(error){results.add({'case':c,'stopped':false,'error':'$error'});}}save('$raw/cleanup-${DateTime.now().microsecondsSinceEpoch}.json',{'rows':results,'passed':results.every((r)=>r['stopped']==true)});require(results.every((r)=>r['stopped']==true),'Owned cleanup incomplete');}
List<Map<String,dynamic>> cases()=>(jsonDecode(File('$raw/cases.json').readAsStringSync()) as List).cast<Map<String,dynamic>>();
void verifyTree(Map<String,dynamic> spec,String output,Map<String,String> env,String id){final files=(spec['files'] as List).cast<Map<String,dynamic>>();require(Directory(output).listSync(followLinks:false).length==1,'Exact output root');require(FileSystemEntity.typeSync('$output/data',followLinks:false)==FileSystemEntityType.directory,'Data directory type');final actual=Directory('$output/data').listSync(recursive:true,followLinks:false);require(actual.length==files.length,'Exact file count');final expected=files.map((f)=>'$output/data/${f['name']}').toSet();for(final e in actual){require(expected.remove(e.path)&&FileSystemEntity.typeSync(e.path,followLinks:false)==FileSystemEntityType.file,'Exact names and regular files');require((e.statSync().mode&0x1ff)==0x1a4,'Default file0644');}require(expected.isEmpty,'No missing file');for(final p in [output,'$output/data'])require((Directory(p).statSync().mode&0x1ff)==0x1ed,'Default directory0755');run(['/usr/bin/diff','--brief','--recursive','--',spec['source_directory'] as String,'$output/data'],env,'$id-byte-tree');run(['/usr/bin/sync','-d','--',...actual.map((e)=>e.path), '$output/data',output],env,'$id-drain',maximum:60);}
Future<void> verifyConcatenation(List<String> files,String source,Map<String,String> env)async{
 final remaining=1800-wall.elapsed.inSeconds-60;require(remaining>0,'Concatenation deadline');final seconds=remaining<120?remaining:120;
 final producerArgs=['--kill-after=10s','$seconds','/usr/bin/cat','--',...files];final compareArgs=['--kill-after=10s','$seconds','/usr/bin/cmp','-s','--',source,'-'];
 final producer=await Process.start('/usr/bin/timeout',producerArgs,environment:env,includeParentEnvironment:false);
 final compare=await Process.start('/usr/bin/timeout',compareArgs,environment:env,includeParentEnvironment:false);
 final errors=Future.wait([producer.stderr.transform(utf8.decoder).join(),compare.stderr.transform(utf8.decoder).join(),compare.stdout.transform(utf8.decoder).join()]);
 Object? failure;try{await producer.stdout.pipe(compare.stdin);}catch(error){failure=error;producer.kill(ProcessSignal.sigterm);compare.kill(ProcessSignal.sigterm);}
 final codes=await Future.wait([producer.exitCode,compare.exitCode]);final diagnostics=await errors;
 save('$raw/commands/${(counter++).toString().padLeft(5,'0')}-concatenation.json',{'producer_argv':['/usr/bin/timeout',...producerArgs],'compare_argv':['/usr/bin/timeout',...compareArgs],'exit_codes':codes,'producer_stderr':diagnostics[0],'compare_stderr':diagnostics[1],'compare_stdout':diagnostics[2],'stream_failure':failure?.toString(),'passed':failure==null&&codes.every((v)=>v==0),'source_bytes':File(source).lengthSync(),'file_count':files.length,'payload_not_logged':true});
 require(failure==null&&codes.every((v)=>v==0),'Concatenated sources differ from pinned input');
}
Future<void> setup()async{require(!File('$raw/cases.json').existsSync(),'Existing setup');Directory(owned).createSync(recursive:true);require(sha(cli)==expectedCli,'Pinned CLI');final previous=(jsonDecode(File('$worktree/docs/evidence/native-public-extraction-2026-10-11/raw/cases.json').readAsStringSync()) as List).where((v)=>(v['name'] as String).startsWith('source-zstd')).toList();require(previous.length==2,'Inputs');final records=<Map<String,dynamic>>[];final started=<int>[];try{for(var c=0;c<2;c++){final input=previous[c];final sourceRow=(input['variants'] as List).singleWhere((v)=>v['variant']=='A');final source=sourceRow['source_path'] as String;require(sha(source)==sourceRow['source_sha256'],'Pinned source');final count=c==0?256:1024;final unit=c==0?256*1024:1024*1024;require(input['bytes']==count*unit,'Shape');budget(count*unit*3);final root='$owned/fixture$c';require(!Directory(root).existsSync(),'Existing partial fixture');Directory('$root/source').createSync(recursive:true);final env=environment(c);final file=File(source).openSync();final buffer=Uint8List(unit);final entries=<Map<String,dynamic>>[];try{for(var n=0;n<count;n++){require(file.readIntoSync(buffer)==unit,'Input EOF');final name='file-${n.toString().padLeft(6,'0')}.bin';final p='$root/source/$name';File(p).writeAsBytesSync(buffer);entries.add({'name':name,'bytes':unit,'sha256':sha(p)});}require(file.readByteSync()==-1,'Extra input');}finally{file.closeSync();}await verifyConcatenation(entries.map((v)=>'$root/source/${v['name']}').toList(),source,env);started.add(c);agent(c,start:true);final archive='$root/archive.lbox';run([cli,archive,'create','--encryption','none','--signing','none','--compression','zstd'],env,'create$c');run([cli,archive,'add','--recursive','$root/source','--to','/data'],env,'import$c');final spec=<String,dynamic>{'case':c==0?'256-source-files-64mib':'1024-source-files-1gib','root':root,'source_directory':'$root/source','source':source,'source_sha256':sourceRow['source_sha256'],'bytes':count*unit,'files':entries,'concatenation_verified':true,'archive_sha256':sha(archive),'archive_bytes':File(archive).lengthSync()};require(File(archive).lengthSync()<count*unit,'Compressed archive must be smaller than logical payload');spec['compressed_size_admission']=true;final output='$root/setup-output';run([cli,archive,'extract','--to',output],env,'setup-extract$c');verifyTree(spec,output,env,'setup$c');Directory(output).deleteSync(recursive:true);records.add(spec);}}finally{cleanupAgents(started);}save('$raw/cases.json',records);print(green('Public many-file fixtures verified.'));}
void freeze(){require(!File('$raw/fixture-identities.json').existsSync(),'Existing freeze');require(sha(cli)==expectedCli,'CLI build identity');final hashes=<String,String>{};for(final p in [cli,Platform.script.toFilePath(),'$evidence/README.md','$raw/cases.json'])hashes[p]=sha(p);for(final spec in cases()){hashes['${spec['root']}/archive.lbox']=sha('${spec['root']}/archive.lbox');require(hashes['${spec['root']}/archive.lbox']==spec['archive_sha256'],'Archive changed');for(final f in spec['files']){final p='${spec['source_directory']}/${f['name']}';hashes[p]=sha(p);require(hashes[p]==f['sha256'],'Source changed');}}save('$raw/fixture-identities.json',{'hashes':hashes,'planned_processes':56,'umask':'0022','source_epoch':'credential-open build-new manifest, preserved b6da783e plus reviewed runtime diff','cli_build_manifest_sha256':sha('$worktree/docs/evidence/credential-open-2026-10-12/raw/build-new/manifest.txt')});}
void identities(){for(final e in (object('$raw/fixture-identities.json')['hashes'] as Map).entries)require(sha(e.key)==e.value,'Changed identity');}
