 require(sha(cli)==expectedCli&&sha(trialCli)==expectedTrial,'Pinned old/new executables');
 final hashes=<String,String>{};
 for(final e in (object('$raw/fixture-identities.json')['hashes'] as Map).entries){
  if(e.key==Platform.script.toFilePath()||e.key=='$evidence/README.md')continue;
  require(sha(e.key)==e.value,'Baseline fixture identity changed');hashes[e.key]=e.value;
 }
 final manifest='$prior/build-new/manifest.txt';final build=File(manifest).readAsStringSync();final original=object('$prior/paired-identities.json');require(sha(manifest)==original['hashes'][manifest],'Preserved build manifest changed');final buildSources=<String,String>{};
 require(build.contains('$expectedTrial  target/parallel-extraction-202612/bin/lockbox-new'),'Build executable identity');
