 for(final p in [trialCli,Platform.script.toFilePath(),'$evidence/README.md',manifest,'$prior/paired-identities.json','$raw/fixture-identities.json'])hashes[p]=sha(p);
 save('$raw/paired-identities.json',{'hashes':hashes,'planned_processes':56,'preparation_processes':8,'measured_processes':48,'umask':'0022','base':'d26e5ce6','original_build_base':'a881d15de5710527c60a8584147d9f5110c00a33','build_source_hashes':buildSources,'source_note':'Reused exact raw-trial binaries and original build source hashes; current tree additionally contains tests and hook formatting. No rebuild.','variants':{'old':cli,'new':trialCli},'decision':'every new measured RSS below100000000bytes; aggregate paired elapsed95%upper at most1.05; exact output/identity gates'});
}
