void pairedBatch(){
 pairedIdentities();final output=File('$raw/paired-samples.jsonl');require(!output.existsSync(),'Existing paired batch');final specs=cases();final started=<int>[];var accepted=0;
 try{for(var c=0;c<2;c++){started.add(c);agent(c,start:true);final spec=specs[c];final env=environment(c);
  for(var r=0;r<14;r++){final order=(r+c)%2==0?['old','new']:['new','old'];
   for(var position=0;position<2;position++){final variant=order[position];final executable=variant=='old'?cli:trialCli;final id='paired-c$c-r$r-p$position-$variant';final destination='${spec['root']}/output-$id';require(!Directory(destination).existsSync(),'Output exists');budget(spec['bytes'] as int);cold('${spec['root']}/archive.lbox',env,id);final timing='$raw/$id.time';
    run(['/usr/bin/time','-f','%e %U %S %M','-o',timing,'/usr/bin/taskset','-c','0-4',executable,'${spec['root']}/archive.lbox','extract','--to',destination],env,id);
    final metrics=File(timing).readAsStringSync().trim().split(RegExp(r'\s+')).map(double.parse).toList();require(metrics.length==4&&metrics.every((v)=>v.isFinite&&v>=0)&&metrics[0]>0&&metrics[3]>0,'Metrics');verifyTree(spec,destination,env,id);Directory(destination).deleteSync(recursive:true);
    output.writeAsStringSync('${jsonEncode({'case':spec['case'],'round':r,'position':position,'variant':variant,'preparation':r<2,'elapsed_seconds':metrics[0],'user_seconds':metrics[1],'system_seconds':metrics[2],'rss_bytes':metrics[3]*1024,'exact_tree_bytes_modes_verified':true,'cold_archive':true,'output_drained':true,'executable':executable})}\n',mode:FileMode.append,flush:true);accepted++;
   }
  }
 }}finally{cleanupAgents(started);}pairedIdentities();require(accepted==56,'Exact56');save('$raw/paired-complete.json',{'accepted':accepted,'measured':48,'preparation':8,'identities_verified_after':true,'owned_agents_stopped':true,'wall_seconds':wall.elapsedMilliseconds/1000});
}

Future<void> main(List<String> args)async{require(Platform.isLinux&&args.length==1,'Linux setup | freeze | freeze-paired | paired');final setMask=DynamicLibrary.process().lookupFunction<Uint32 Function(Uint32),int Function(int)>('umask');final previous=setMask(0x12);try{Directory(raw).createSync(recursive:true);counter=Directory('$raw/commands').existsSync()?Directory('$raw/commands').listSync().whereType<File>().length:0;switch(args.single){case 'setup':await setup();break;case 'freeze':freeze();break;case 'freeze-paired':freezePaired();break;case 'paired':pairedBatch();break;default:throw ArgumentError('Unknown phase');}}finally{setMask(previous);}}
